#include "GenerateMeshUsingSimmetrix.h"
#include "GeometryReader.h"
#include "GeometryWriter.h"
#include "MeshGenerationParameters.h"
#include <boost/algorithm/string/predicate.hpp>
#include <boost/algorithm/string/trim.hpp>
#include <boost/filesystem.hpp>
#include <boost/program_options.hpp>
#include <iterator>
#include <vector>
#include <map>
#include <math.h>


int main ( int argc, char *argv[] )
{
    time_t start_time = time(&start_time);

    std::string input_model_file;
    std::string input_tree_file;
    std::string input_filename_file;
    std::string output_mesh_file;
    double grid_size = -1;
    bool run_mesh_adaptation = false;
    bool append_data = false;
    bool generate_boundary_layers = false;
    bool constrain_surface_mesh = false;
    bool write_outputs_only = false;
    bool generate_surface_id = true;
    double boundary_layer_thickness = 0.05;
    double radius_based_ratio = 4.0;
    int wall_surface_id = 1;
    int number_of_boundary_layers = 3;

    boost::program_options::options_description command_line_options("Command line options");
    command_line_options.add_options()
        ("input_model_file",
         boost::program_options::value<std::string>(&input_model_file)->default_value("model.vtp"),
         "input tissue mesh file - need to be a discretized triangulated mesh format (default is model.vtp)")
        ("grid_size",
         boost::program_options::value<double>(&grid_size)->default_value(1.0),
         "desired grid size (default is 1.0")
        ("output_mesh_file",
         boost::program_options::value<std::string>(&output_mesh_file)->default_value("volume_mesh.vtu"),
         "output tissue mesh file appended with attributes (default is volume_mesh.vtu)")
        ("mesh_adaptation",
         boost::program_options::value<bool>(&run_mesh_adaptation)->default_value(false),
         "configure to execute mesh adaptation (default is false)")
        ("input_tree_file",
         boost::program_options::value<std::string>(&input_tree_file)->default_value(""),
         "input tree data to be used for mesh adaptation")
        ("input_filename_file",
         boost::program_options::value<std::string>(&input_filename_file)->default_value(""),
         "input filename file (default is empty)")
        ("append_data",
         boost::program_options::value<bool>(&append_data)->default_value(false),
         "append additional data to the volume mesh (default is false)")
        ("generate_boundary_layers",
         boost::program_options::value<bool>(&generate_boundary_layers)->default_value(false),
         "generate boundary layers (default is false)")
        ("constrain_surface_mesh",
         boost::program_options::value<bool>(&constrain_surface_mesh)->default_value(false),
         "constrain surface mesh (default is false)")
        ("write_outputs_only",
         boost::program_options::value<bool>(&write_outputs_only)->default_value(false),
         "write mesh outputs only - need to read output_mesh_file (default is false)")
        ("generate_surface_id",
         boost::program_options::value<bool>(&generate_surface_id)->default_value(true),
         "generate surface id (default is true)") // ChangMinLee
        ("boundary_layer_thickness",
         boost::program_options::value<double>(&boundary_layer_thickness)->default_value(0.05),
         "boundary layer thickness (default is 0.05)")
        ("radius_based_ratio",
         boost::program_options::value<double>(&radius_based_ratio)->default_value(4.0),
         "radius based refinement ratio (default is 4.0)")
        ("wall_surface_id",
         boost::program_options::value<int>(&wall_surface_id)->default_value(1),
         "wall surface id (default is 1)")
        ("number_of_boundary_layers",
         boost::program_options::value<int>(&number_of_boundary_layers)->default_value(3),
         "number of boundary layers (default is 3)")
        ("help", "Print usage");
    boost::program_options::variables_map config_map;

    try
    {
        store(boost::program_options::parse_command_line(argc, argv, command_line_options), config_map);
        notify(config_map);
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error: " << ex.what() << std::endl;
        return 1;
    }
    if (config_map.count("help"))
    {
        std::cerr << "Usage: " << command_line_options << std::endl;
        return 1;
    }
    if (run_mesh_adaptation &&
        input_tree_file.size() > 0 &&
        input_tree_file.compare(input_tree_file.size() - 4, 4, ".vtp") != 0)
    {
        std::cerr << "Error: invalid file format. Only input vtp" << std::endl;
        return 1;
    }
    if (!input_filename_file.empty() && !boost::filesystem::exists(input_filename_file))
    {
        std::cerr << "Error: file " << input_filename_file << " does not exist";
        return 1;
    }

    try
    {
        // read input mesh file
        GeometryReader mesh_reader;
        mesh_reader.read(input_model_file);
        GeometryData model = mesh_reader.geometry_data();

        MeshGenerationParameters mesh_params;
        mesh_params.adapt_mesh(run_mesh_adaptation);
        mesh_params.generate_boundary_layers(generate_boundary_layers);
        mesh_params.constrain_surface_mesh(constrain_surface_mesh);
        mesh_params.append_mesh_data(append_data);
        mesh_params.boundary_layer_thickness(boundary_layer_thickness);
        mesh_params.refinement_ratio(radius_based_ratio);
        mesh_params.global_mesh_size(grid_size);
        mesh_params.boundary_surface_id(wall_surface_id);
        mesh_params.number_of_boundary_layers(number_of_boundary_layers);
        mesh_params.write_outputs_only(write_outputs_only);
        mesh_params.generate_surface_id(generate_surface_id);
        mesh_params.output_mesh_file(output_mesh_file);
        mesh_params.input_filename_file(input_filename_file);
        mesh_params.debug();
        GenerateMeshUsingSimmetrix mesh_generator(model, input_tree_file, mesh_params);
        if (mesh_generator.generate() == 0)
        {
            mesh_generator.write();
        }
        else
        {
            throw "MeshGenerator failed constructing a mesh";
        }
    }
    catch (const std::string& exception)
    {
        std::cerr << exception << std::endl;
        return 1;
    }
    catch (const char* exception)
    {
        std::cerr << exception << std::endl;
        return 1;
    }

    time_t end_time = time(&end_time);
    std::cout << "MeshGenerator: duration: " << end_time - start_time << " seconds" << std::endl;
    return 0;
}

