void GeometryReader::read(const std::string& geometry_file)
{
    assert (boost::filesystem::exists(geometry_file));
    if (geometry_file.compare(geometry_file.size()-4, 4, ".vtu") == 0)
    {
        std::cout << "read a volume mesh data " << geometry_file << std::endl;
        // _read_vtu(geometry_file);
        _read_vtu_multi_domain(geometry_file);
    }
    else if (geometry_file.compare(geometry_file.size()-4, 4, ".vtp") == 0)
    {
        std::cout << "read a surface mesh data " << geometry_file << std::endl;
        _read_vtp(geometry_file);
    }
    else if (geometry_file.size() >= 7 && geometry_file.compare(geometry_file.size()-7, 7, "old.vtk") == 0)
    {
        std::cout << "read a legacy surface mesh data " << geometry_file << std::endl;
        _read_legacy_vtk(geometry_file);
    }
    else if (geometry_file.compare(geometry_file.size()-4, 4, ".vtk") == 0)
    {
        std::cout << "read a unstructured surface mesh data " << geometry_file << std::endl;
        _read_vtk(geometry_file);
    }
    else if (geometry_file.compare(geometry_file.size()-4, 4, ".stl") == 0)
    {
        std::cout << "read a STL surface mesh data " << geometry_file << std::endl;
        _read_stl(geometry_file);
    }
    else if (geometry_file.compare(geometry_file.size()-4, 4, ".obj") == 0)
    {
        std::cout << "read a OBJ surface mesh data " << geometry_file << std::endl;
        _read_obj(geometry_file);
    }
    else
    {
        std::ostringstream message;
        message << "Input file " << geometry_file << " is not suported";
        throw message.str();
    }
    std::cout << "Input geometry " << geometry_file << " contains "
              << _geometry_data.number_vertices() << " vertices and "
              << _geometry_data.number_elements() << " elements" << std::endl;
}



